    private static readonly Dictionary<string, Geometry> Cache = new(StringComparer.Ordinal);

    /// <summary>Returns the cached geometry for a source icon key.</summary>
    public static Geometry Get(string key)
    {
        if (Cache.TryGetValue(key, out var cached)) return cached;
        if (!Definitions.TryGetValue(key, out var data))
            throw new ArgumentOutOfRangeException(nameof(key), key, "Unknown source icon.");
        var geometry = Geometry.Parse(data);
        Cache[key] = geometry;
        return geometry;
    }

    /// <summary>
    /// Creates a fill-only icon shape that fits a square slot of <paramref name="size"/> while
    /// keeping the source aspect ratio.
    /// </summary>
    public static Shape Create(string key, double size, IBrush brush)
    {
        var geometry = Get(key);
        var bounds = geometry.Bounds;
        var longest = Math.Max(bounds.Width, bounds.Height);
        var scale = longest > 0 ? size / longest : 0;
        return new ShapePath
        {
            Data = geometry,
            Fill = brush,
            Stretch = Stretch.Uniform,
            Width = bounds.Width * scale,
            Height = bounds.Height * scale,
            HorizontalAlignment = HorizontalAlignment.Center,
            VerticalAlignment = VerticalAlignment.Center,
            IsHitTestVisible = false
        };
    }
}
